import os, json, datetime, numpy as np
def now(): return datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
def ensure_dir(p): os.makedirs(p, exist_ok=True)
def readj(p): 
    with open(p, "r", encoding="utf-8") as f: 
        return json.load(f)
def writej(p, o):
    ensure_dir(os.path.dirname(p))
    with open(p, "w", encoding="utf-8") as f: json.dump(o, f, ensure_ascii=False, indent=2, sort_keys=True)
def append_status(p, s):
    ensure_dir(os.path.dirname(p))
    with open(p, "a", encoding="utf-8") as f: f.write(s)

def parse_pairs(d):
    rows = d.get("pairs_sorted") if isinstance(d, dict) else None
    if not rows or not isinstance(rows, list): return None
    vals = []
    for it in rows:
        if isinstance(it, (list, tuple)) and len(it) >= 3:
            try: vals.append(float(it[2]))
            except: pass
    return np.array(vals, dtype=float) if vals else None

def construct_packing():
    ts = now()
    shared = os.path.join("storage", "shared", "appxE_contribs")
    out_root = os.path.join("storage", "noesis", "nmap")
    results = os.path.join(out_root, "results")
    ensure_dir(results)
    status_path = os.path.join(out_root, "AGGREGATOR_v2_1_STATUS.md")
    quest_path = os.path.join(shared, "quest_II_latest_packing_slacks_clearances.json")
    quality = {
        "version": "v2.1",
        "timestamp_utc": ts,
        "source": quest_path if os.path.exists(quest_path) else None,
        "present": os.path.exists(quest_path),
        "usable": False,
        "reason": None,
        "stats": None
    }
    if os.path.exists(quest_path):
        d = readj(quest_path)
        sl = parse_pairs(d)
        b = np.array(d.get("boundary_clearances", []), dtype=float) if isinstance(d, dict) else np.array([])
        r = np.array(d.get("radii", []), dtype=float) if isinstance(d, dict) else np.array([])
        if sl is None or sl.size == 0:
            quality["usable"] = False; quality["reason"] = "no_pairs_or_parse_failed"
        else:
            s_min, s_max = float(np.min(sl)), float(np.max(sl))
            s_std = float(np.std(sl))
            b_std = float(np.std(b)) if b.size else None
            r_std = float(np.std(r)) if r.size else None
            quality["stats"] = {"slack_min": s_min, "slack_max": s_max, "slack_std": s_std, "boundary_std": b_std, "radii_std": r_std}
            # Degeneracy: all pair slacks nearly equal and negative; boundary and radii near-constant placeholders
            if (s_max - s_min) < 1e-14 and s_max < 0 and (b_std is not None and b_std < 1e-12) and (r_std is not None and r_std < 1e-15):
                quality["usable"] = False; quality["reason"] = "degenerate_placeholders_detected"
            else:
                quality["usable"] = True
    else:
        quality["usable"] = False; quality["reason"] = "missing_file"

    writej(os.path.join(results, "quest_latest_slacks_quality.json"), quality)
    msg = f"\n[{ts}] Quest latest slacks quality: usable={quality['usable']}, reason={quality['reason']}, stats={quality['stats']}\n"
    append_status(status_path, msg)

    # Return trivial valid packing
    centers, radii = [], []
    r0 = 0.06
    for i in range(5):
        for j in range(6):
            if len(centers) < 26:
                centers.append([0.1 + 0.2*i, 0.1 + 0.15*j]); radii.append(r0)
    return np.array(centers, float), np.array(radii, float)
